insert into public.chapters (id, status, launched_on, lead_name, lead_photo, member_count, member_count_as_of, cover_image, is_flagship, is_published, slug, city, state, latitude, longitude, sort_order, intro) values
  ('00000000-0000-4000-8000-000000000010', 'active', null, null, null, null, null, '/photos/meetup-garden-room.webp', true, true, 'mumbai', 'Mumbai', 'Maharashtra', 19.076, 72.8777, 10, 'Where BNC started. The flagship chapter runs the most rooms in the circle — founder networking, startup conversations and pitch sessions in cafés and studios across the city.'),
  ('00000000-0000-4000-8000-000000000020', 'active', null, null, null, null, null, null, false, true, 'bangalore', 'Bangalore', 'Karnataka', 12.9716, 77.5946, 20, 'Rooms for Bangalore''s product founders, engineers and operators — people who build software and want to meet the people who sell, fund and hire for it.'),
  ('00000000-0000-4000-8000-000000000030', 'active', null, null, null, null, null, null, false, true, 'delhi-ncr', 'Delhi NCR', 'Delhi', 28.6139, 77.209, 30, 'One chapter across Delhi, Gurugram and Noida, for founders and operators who would rather meet across the table than across a feed.'),
  ('00000000-0000-4000-8000-000000000040', 'active', null, null, null, null, null, null, false, true, 'pune', 'Pune', 'Maharashtra', 18.5204, 73.8567, 40, 'Pune''s founders, freelancers and students in one room — close enough to Mumbai that members move between both chapters.'),
  ('00000000-0000-4000-8000-000000000050', 'active', null, null, null, null, null, null, false, true, 'hyderabad', 'Hyderabad', 'Telangana', 17.385, 78.4867, 50, 'Rooms for Hyderabad''s builders — first-time founders, tech operators and the freelancers who work with them.'),
  ('00000000-0000-4000-8000-000000000060', 'active', null, null, null, null, null, null, false, true, 'ahmedabad', 'Ahmedabad', 'Gujarat', 23.0225, 72.5714, 60, 'One of BNC''s newer chapters, for Ahmedabad founders and family-business successors building something of their own.'),
  ('00000000-0000-4000-8000-000000000070', 'active', null, null, null, null, null, null, false, true, 'nashik', 'Nashik', 'Maharashtra', 19.9975, 73.7898, 70, 'Proof that founder rooms aren''t only for metros. Nashik''s builders meet locally and plug into the circle across eight cities.'),
  ('00000000-0000-4000-8000-000000000080', 'active', null, null, null, null, null, null, false, true, 'surat', 'Surat', 'Gujarat', 21.1702, 72.8311, 80, 'For Surat''s founders and operators — textile, diamond and D2C businesses alongside new tech startups.')
